55	/**
56	 * Reconciler for {@link Post}.
57	 *
58	 * <p>things to do:
59	 *
60	 * <ul>
61	 *   1. generate permalink 2. generate excerpt if auto generate is enabled
62	 * </ul>
63	 *
64	 * @author guqing
65	 * @since 2.0.0
66	 */
67	@Slf4j
68	@AllArgsConstructor
69	@Component
70	public class PostReconciler implements Reconciler<Reconciler.Request> {
71	    private static final Duration BLOCKING_TIMEOUT = ReactiveUtils.DEFAULT_TIMEOUT;
72	    private static final String FINALIZER_NAME = "post-protection";
73	    private final ExtensionClient client;
74	    private final PostService postService;
75	    private final PostPermalinkPolicy postPermalinkPolicy;
76	    private final CounterService counterService;
77	    private final CommentService commentService;
78	    private final CategoryService categoryService;
79	    private final ExtensionGetter extensionGetter;
80	
81	    private final ApplicationEventPublisher eventPublisher;
82	    private final NotificationCenter notificationCenter;
83	
84	    @Override
85	    public Result reconcile(Request request) {
86	        var events = new LinkedHashSet<ApplicationEvent>();
87	        client.fetch(Post.class, request.name()).ifPresent(post -> {
88	            if (ExtensionOperator.isDeleted(post)) {
89	                removeFinalizers(post.getMetadata(), Set.of(FINALIZER_NAME));
90	                unPublishPost(post, events);
91	                events.add(new PostDeletedEvent(this, post));
92	                cleanUpResources(post);
93	                // update post to be able to be collected by gc collector.
94	                client.update(post);
95	                // fire event after updating post
96	                events.forEach(eventPublisher::publishEvent);
97	                return;
98	            }
99	            addFinalizers(post.getMetadata(), Set.of(FINALIZER_NAME));
100	
101	            populateLabels(post, events);
102	
103	            schedulePublishIfNecessary(post);
104	
105	            subscribeNewCommentNotification(post);
106	
107	            var status = post.getStatus();
108	            if (status == null) {
109	                status = new Post.PostStatus();
110	                post.setStatus(status);
111	            }
112	
113	            if (post.isPublished() && post.getSpec().getPublishTime() == null) {
114	                post.getSpec().setPublishTime(Instant.now());
115	            }
116	
117	            // calculate the sha256sum
118	            var configSha256sum = Hashing.sha256()
119	                    .hashString(post.getSpec().toString(), UTF_8)
120	                    .toString();
121	
122	            var annotations = nullSafeAnnotations(post);
123	            var oldConfigChecksum = annotations.get(Constant.CHECKSUM_CONFIG_ANNO);
124	            if (!Objects.equals(oldConfigChecksum, configSha256sum)) {
125	                // if the checksum doesn't match
126	                events.add(new PostUpdatedEvent(this, post.getMetadata().getName()));
127	                annotations.put(Constant.CHECKSUM_CONFIG_ANNO, configSha256sum);
128	            }
129	
130	            if (shouldUnPublish(post)) {
131	                unPublishPost(post, events);
132	            } else {
133	                publishPost(post, events);
134	            }
135	
136	            if (!annotations.containsKey(Constant.PERMALINK_PATTERN_ANNO)) {
137	                // only set the permalink pattern if not present
138	                var permalinkPattern = postPermalinkPolicy.pattern();
139	                annotations.put(Constant.PERMALINK_PATTERN_ANNO, permalinkPattern);
140	            }
141	            status.setPermalink(postPermalinkPolicy.permalink(post));
142	            if (status.getPhase() == null) {
143	                status.setPhase(PostPhase.DRAFT.toString());
144	            }
145	
146	            var excerpt = post.getSpec().getExcerpt();
147	            if (excerpt == null) {
148	                excerpt = new Post.Excerpt();
149	            }
150	            var isAutoGenerate = defaultIfNull(excerpt.getAutoGenerate(), true);
151	            if (isAutoGenerate) {
152	                status.setExcerpt(getExcerpt(post));
153	            } else {
154	                status.setExcerpt(excerpt.getRaw());
155	            }
156	
157	            var ref = Ref.of(post);
158	            // handle contributors
159	            var headSnapshot = post.getSpec().getHeadSnapshot();
160	            var snapshotContributors = listSnapshots(ref).stream()
161	                    .map(snapshot -> {
162	                        Set<String> usernames = snapshot.getSpec().getContributors();
163	                        return Objects.requireNonNullElseGet(usernames, () -> new HashSet<String>());
164	                    })
165	                    .flatMap(Set::stream);
166	            // the owner is always treated as a contributor, even if they never edited the content
167	            // see https://github.com/halo-dev/halo/issues/8284
168	            var ownerContributor = Stream.ofNullable(post.getSpec().getOwner()).filter(StringUtils::isNotBlank);
169	            var contributors = Stream.concat(snapshotContributors, ownerContributor)
170	                    .distinct()
171	                    .sorted()
172	                    .toList();
173	            status.setContributors(contributors);
174	
175	            // update in progress status
176	            status.setInProgress(
177	                    !StringUtils.equals(headSnapshot, post.getSpec().getReleaseSnapshot()));
178	
179	            computeHiddenState(post);
180	
181	            // version + 1 is required to truly equal version
182	            // as a version will be incremented after the update
183	            status.setObservedVersion(post.getMetadata().getVersion() + 1);
184	            client.update(post);
185	
186	            // fire event after updating post
187	            events.forEach(eventPublisher::publishEvent);
188	        });
189	        return Result.doNotRetry();
190	    }
191	
192	    private void computeHiddenState(Post post) {
193	        var categories = post.getSpec().getCategories();
194	        if (categories == null) {
195	            post.getStatusOrDefault().setHideFromList(false);
196	            return;
197	        }
198	        var hidden = categories.stream()
199	                .anyMatch(categoryName -> categoryService
200	                        .isCategoryHidden(categoryName)
201	                        .blockOptional(BLOCKING_TIMEOUT)
202	                        .orElse(false));
203	        post.getStatusOrDefault().setHideFromList(hidden);
204	    }
205	
206	    private void populateLabels(Post post, Set<ApplicationEvent> events) {
207	        var labels = nullSafeLabels(post);
208	        labels.put(Post.DELETED_LABEL, String.valueOf(isTrue(post.getSpec().getDeleted())));
209	
210	        var expectVisible = defaultIfNull(post.getSpec().getVisible(), VisibleEnum.PUBLIC);
211	        var oldVisible = VisibleEnum.from(labels.get(Post.VISIBLE_LABEL));
212	        if (!Objects.equals(oldVisible, expectVisible)) {
213	            var postName = post.getMetadata().getName();
214	            events.add(new PostVisibleChangedEvent(this, postName, oldVisible, expectVisible));
215	        }
216	        labels.put(Post.VISIBLE_LABEL, expectVisible.toString());
217	
218	        var ownerName = post.getSpec().getOwner();
219	        if (StringUtils.isNotBlank(ownerName)) {
220	            labels.put(Post.OWNER_LABEL, ownerName);
221	        }
222	
223	        var publishTime = post.getSpec().getPublishTime();
224	        if (publishTime != null) {
225	            labels.put(Post.ARCHIVE_YEAR_LABEL, HaloUtils.getYearText(publishTime));
226	            labels.put(Post.ARCHIVE_MONTH_LABEL, HaloUtils.getMonthText(publishTime));
227	            labels.put(Post.ARCHIVE_DAY_LABEL, HaloUtils.getDayText(publishTime));
228	        }
229	
230	        if (!labels.containsKey(Post.PUBLISHED_LABEL)) {
231	            labels.put(Post.PUBLISHED_LABEL, BooleanUtils.FALSE);
232	        }
233	    }
234	
235	    private static boolean shouldUnPublish(Post post) {
236	        return isTrue(post.getSpec().getDeleted()) || isFalse(post.getSpec().getPublish());
237	    }
238	
239	    @Override
240	    public Controller setupWith(ControllerBuilder builder) {
241	        return builder.extension(new Post())
242	                .syncAllListOptions(ListOptions.builder()
243	                        .andQuery(Queries.equal(Post.REQUIRE_SYNC_ON_STARTUP_INDEX_NAME, true))
244	                        .build())
245	                .build();
246	    }
