248	    void schedulePublishIfNecessary(Post post) {
249	        var labels = nullSafeLabels(post);
250	        // ensure the label is removed
251	        labels.remove(Post.SCHEDULING_PUBLISH_LABEL);
252	
253	        final var now = Instant.now();
254	        var publishTime = post.getSpec().getPublishTime();
255	        if (post.isPublished() || publishTime == null) {
256	            return;
257	        }
258	
259	        // expect to publish in the future
260	        if (isTrue(post.getSpec().getPublish()) && publishTime.isAfter(now)) {
261	            labels.put(Post.SCHEDULING_PUBLISH_LABEL, TRUE);
262	            // update post changes before requeue
263	            client.update(post);
264	
265	            throw new RequeueException(
266	                    Result.requeue(Duration.between(now, publishTime)), "Requeue for scheduled publish.");
267	        }
268	    }
269	
270	    void subscribeNewCommentNotification(Post post) {
271	        var subscriber = new Subscription.Subscriber();
272	        subscriber.setName(post.getSpec().getOwner());
273	
274	        var interestReason = new Subscription.InterestReason();
275	        interestReason.setReasonType(NotificationReasonConst.NEW_COMMENT_ON_POST);
276	        interestReason.setExpression(
277	                "props.postOwner == '%s'".formatted(post.getSpec().getOwner()));
278	        notificationCenter.subscribe(subscriber, interestReason).block(BLOCKING_TIMEOUT);
279	    }
280	
281	    private void publishPost(Post post, Set<ApplicationEvent> events) {
282	        var expectReleaseSnapshot = post.getSpec().getReleaseSnapshot();
283	        if (StringUtils.isBlank(expectReleaseSnapshot)) {
284	            // Do nothing if release snapshot is not set
285	            return;
286	        }
287	        var annotations = post.getMetadata().getAnnotations();
288	        var lastReleaseSnapshot = annotations.get(Post.LAST_RELEASED_SNAPSHOT_ANNO);
289	        if (post.isPublished() && Objects.equals(expectReleaseSnapshot, lastReleaseSnapshot)) {
290	            // If the release snapshot is not change
291	            return;
292	        }
293	        var status = post.getStatus();
294	        // validate the release snapshot
295	        var snapshot = client.fetch(Snapshot.class, expectReleaseSnapshot);
296	        if (snapshot.isEmpty()) {
297	            Condition condition = Condition.builder()
298	                    .type(PostPhase.FAILED.name())
299	                    .reason("SnapshotNotFound")
300	                    .message(String.format("Snapshot [%s] not found for publish", expectReleaseSnapshot))
301	                    .status(ConditionStatus.FALSE)
302	                    .lastTransitionTime(Instant.now())
303	                    .build();
304	            status.getConditionsOrDefault().addAndEvictFIFO(condition);
305	            status.setPhase(PostPhase.FAILED.name());
306	            return;
307	        }
308	        annotations.put(Post.LAST_RELEASED_SNAPSHOT_ANNO, expectReleaseSnapshot);
309	        status.setPhase(PostPhase.PUBLISHED.toString());
310	        var condition = Condition.builder()
311	                .type(PostPhase.PUBLISHED.name())
312	                .reason("Published")
313	                .message("Post published successfully.")
314	                .lastTransitionTime(Instant.now())
315	                .status(ConditionStatus.TRUE)
316	                .build();
317	        status.getConditionsOrDefault().addAndEvictFIFO(condition);
318	        var labels = post.getMetadata().getLabels();
319	        labels.put(Post.PUBLISHED_LABEL, Boolean.TRUE.toString());
320	        if (post.getSpec().getPublishTime() == null) {
321	            // TODO Set the field in creation hook in the future.
322	            post.getSpec().setPublishTime(Instant.now());
323	        }
324	        status.setLastModifyTime(snapshot.get().getSpec().getLastModifyTime());
325	        events.add(new PostPublishedEvent(this, post.getMetadata().getName()));
326	    }
327	
328	    void unPublishPost(Post post, Set<ApplicationEvent> events) {
329	        if (!post.isPublished()) {
330	            return;
331	        }
332	        var labels = post.getMetadata().getLabels();
333	        labels.put(Post.PUBLISHED_LABEL, Boolean.FALSE.toString());
334	        final var status = post.getStatus();
335	
336	        var condition = new Condition();
337	        condition.setType("CancelledPublish");
338	        condition.setStatus(ConditionStatus.TRUE);
339	        condition.setReason(condition.getType());
340	        condition.setMessage("CancelledPublish");
341	        condition.setLastTransitionTime(Instant.now());
342	        status.getConditionsOrDefault().addAndEvictFIFO(condition);
343	
344	        status.setPhase(PostPhase.DRAFT.toString());
345	
346	        events.add(new PostUnpublishedEvent(this, post.getMetadata().getName()));
347	    }
348	
349	    private void cleanUpResources(Post post) {
350	        // clean up snapshots
351	        final Ref ref = Ref.of(post);
352	        listSnapshots(ref).forEach(client::delete);
353	
354	        // clean up comments
355	        commentService.removeBySubject(ref).block(BLOCKING_TIMEOUT);
356	
357	        // delete counter
358	        counterService
359	                .deleteByName(MeterUtils.nameOf(Post.class, post.getMetadata().getName()))
360	                .block(BLOCKING_TIMEOUT);
361	    }
362	
363	    private String getExcerpt(Post post) {
364	        Optional<ContentWrapper> contentWrapper = postService
365	                .getContent(post.getSpec().getReleaseSnapshot(), post.getSpec().getBaseSnapshot())
366	                .blockOptional(BLOCKING_TIMEOUT);
367	        if (contentWrapper.isEmpty()) {
368	            return StringUtils.EMPTY;
369	        }
370	        var content = contentWrapper.get();
371	
372	        if (StringUtils.isAnyBlank(content.getContent(), content.getRaw())) {
373	            return StringUtils.EMPTY;
374	        }
375	
376	        var contentChecksum =
377	                Hashing.sha256().hashString(content.getContent(), UTF_8).toString();
378	        var excerpt = post.getSpec().getExcerpt();
379	        var isAutoGenerate = excerpt == null || excerpt.getAutoGenerate() == null || excerpt.getAutoGenerate();
380	        var cacheKey = contentChecksum + ":" + isAutoGenerate;
381	        var annotations = MetadataUtil.nullSafeAnnotations(post);
382	        var oldCacheKey = annotations.get(Constant.CONTENT_CHECKSUM_ANNO);
383	        var cachedExcerpt = post.getStatusOrDefault().getExcerpt();
384	        if (Objects.equals(oldCacheKey, cacheKey) && !ExcerptUtils.containsUnpairedSurrogate(cachedExcerpt)) {
385	            return cachedExcerpt;
386	        }
387	        // update the checksum and generate new excerpt
388	        annotations.put(Constant.CONTENT_CHECKSUM_ANNO, cacheKey);
389	
390	        var tags = listTagDisplayNames(post);
391	
392	        var keywords = new HashSet<>(tags);
393	        keywords.add(post.getSpec().getTitle());
394	
395	        var context = new ExcerptGenerator.Context()
396	                .setRaw(content.getRaw())
397	                .setContent(content.getContent())
398	                .setRawType(content.getRawType())
399	                .setKeywords(keywords)
400	                .setMaxLength(160);
401	        return extensionGetter
402	                .getEnabledExtension(ExcerptGenerator.class)
403	                .defaultIfEmpty(new DefaultExcerptGenerator())
404	                .flatMap(generator -> generator.generate(context))
405	                .onErrorResume(Throwable.class, e -> {
406	                    log.error(
407	                            "Failed to generate excerpt for post [{}]",
408	                            post.getMetadata().getName(),
409	                            e);
410	                    return Mono.empty();
411	                })
412	                .blockOptional(BLOCKING_TIMEOUT)
413	                .orElse(StringUtils.EMPTY);
414	    }
415	
416	    private Set<String> listTagDisplayNames(Post post) {
417	        return Optional.ofNullable(post.getSpec().getTags())
418	                .map(tags -> client.listAll(
419	                        Tag.class,
420	                        ListOptions.builder()
421	                                .fieldQuery(in("metadata.name", tags))
422	                                .build(),
423	                        Sort.unsorted()))
424	                .stream()
425	                .flatMap(List::stream)
426	                .map(tag -> tag.getSpec().getDisplayName())
427	                .collect(Collectors.toSet());
428	    }
429	
430	    static class DefaultExcerptGenerator implements ExcerptGenerator {
431	        @Override
432	        public Mono<String> generate(Context context) {
433	            String shortHtmlContent = ExcerptUtils.substringByCodePoints(context.getContent(), 500);
434	            String text = Jsoup.parse(shortHtmlContent).text();
435	            return Mono.just(ExcerptUtils.substringByCodePoints(text, 150));
436	        }
437	    }
438	
439	    List<Snapshot> listSnapshots(Ref ref) {
440	        var snapshotListOptions = new ListOptions();
441	        snapshotListOptions.setFieldSelector(
442	                FieldSelector.of(Queries.equal("spec.subjectRef", Snapshot.toSubjectRefKey(ref))));
443	        return client.listAll(Snapshot.class, snapshotListOptions, Sort.unsorted());
444	    }
445	}
