60	@Slf4j
61	@AllArgsConstructor
62	@Component
63	public class SinglePageReconciler implements Reconciler<Reconciler.Request> {
64	    private static final Duration BLOCKING_TIMEOUT = ReactiveUtils.DEFAULT_TIMEOUT;
65	    private static final String FINALIZER_NAME = "single-page-protection";
66	    private final ExtensionClient client;
67	    private final SinglePageService singlePageService;
68	    private final CounterService counterService;
69	    private final CommentService commentService;
70	    private final ExtensionGetter extensionGetter;
71	
72	    private final ExternalUrlSupplier externalUrlSupplier;
73	
74	    private final NotificationCenter notificationCenter;
75	
76	    private final ApplicationEventPublisher eventPublisher;
77	
78	    @Override
79	    public Result reconcile(Request request) {
80	        client.fetch(SinglePage.class, request.name()).ifPresent(singlePage -> {
81	            if (ExtensionOperator.isDeleted(singlePage)) {
82	                cleanUpResourcesAndRemoveFinalizer(request.name());
83	                eventPublisher.publishEvent(new SinglePageUpdatedEvent(this, singlePage));
84	                return;
85	            }
86	
87	            if (ExtensionUtil.addFinalizers(singlePage.getMetadata(), Set.of(FINALIZER_NAME))) {
88	                client.update(singlePage);
89	            }
90	
91	            subscribeNewCommentNotification(singlePage);
92	
93	            // reconcile spec first
94	            reconcileSpec(request.name());
95	            // then
96	            reconcileMetadata(request.name());
97	            reconcileStatus(request.name());
98	            eventPublisher.publishEvent(new SinglePageUpdatedEvent(this, singlePage));
99	        });
100	        return new Result(false, null);
101	    }
102	
103	    @Override
104	    public Controller setupWith(ControllerBuilder builder) {
105	        return builder.extension(new SinglePage()).build();
106	    }
107	
108	    void subscribeNewCommentNotification(SinglePage page) {
109	        var subscriber = new Subscription.Subscriber();
110	        subscriber.setName(page.getSpec().getOwner());
111	
112	        var interestReason = new Subscription.InterestReason();
113	        interestReason.setReasonType(NotificationReasonConst.NEW_COMMENT_ON_PAGE);
114	        interestReason.setExpression(
115	                "props.pageOwner == '%s'".formatted(page.getSpec().getOwner()));
116	        notificationCenter.subscribe(subscriber, interestReason).block(BLOCKING_TIMEOUT);
117	    }
118	
119	    private void reconcileSpec(String name) {
120	        client.fetch(SinglePage.class, name).ifPresent(page -> {
121	            if (page.isPublished() && page.getSpec().getPublishTime() == null) {
122	                page.getSpec().setPublishTime(Instant.now());
123	            }
124	
125	            // un-publish if necessary
126	            if (page.isPublished() && Objects.equals(false, page.getSpec().getPublish())) {
127	                unPublish(name);
128	                return;
129	            }
130	
131	            try {
132	                publishPage(name);
133	            } catch (Throwable e) {
134	                publishFailed(name, e);
135	                throw e;
136	            }
137	        });
138	    }
139	
140	    private void publishPage(String name) {
141	        client.fetch(SinglePage.class, name)
